import type { ComponentType } from 'react';

/**
 * Every file in `src/tutorials/` exports exactly two things: a default React
 * component and a `tutorial` metadata object. The navigation shell discovers
 * them with `import.meta.glob`, so a tutorial generated by the OMP tools in
 * `src/tools/math-renderer.ts` appears in the shell the moment it is written —
 * no registry to update by hand.
 */

export type TutorialKind =
  /** Elucim SVG scene driven by a frame-based `<Player>`. */
  | 'elucim'
  /** VectorPlay 3D scene (`MainFrame`). */
  | 'vectorplay'
  /** Hand-rolled Three.js scene. */
  | 'three';

export interface TutorialMeta {
  /** URL fragment, e.g. `unit-circle` → `#/unit-circle`. */
  id: string;
  title: string;
  /** One-line description shown in the navigation shell. */
  blurb: string;
  kind: TutorialKind;
  /** Lower sorts first; defaults to 50. */
  order?: number;
  /** Set by the OMP generators so generated tutorials are labeled in the UI. */
  generatedBy?: string;
}

export interface TutorialModule {
  default: ComponentType;
  tutorial: TutorialMeta;
}

const KINDS: readonly TutorialKind[] = ['elucim', 'vectorplay', 'three'];

function isMeta(value: unknown): value is TutorialMeta {
  if (typeof value !== 'object' || value === null) return false;
  const meta = value as Record<string, unknown>;
  return (
    typeof meta.id === 'string' &&
    typeof meta.title === 'string' &&
    typeof meta.blurb === 'string' &&
    typeof meta.kind === 'string' &&
    KINDS.includes(meta.kind as TutorialKind)
  );
}

/**
 * Runtime guard for globbed modules. A tutorial file that is half-written (the
 * OMP generators always write a complete file, but an editor might not be) is
 * skipped rather than crashing the whole shell.
 */
export function isTutorialModule(value: unknown): value is TutorialModule {
  if (typeof value !== 'object' || value === null) return false;
  const mod = value as Record<string, unknown>;
  return typeof mod.default === 'function' && isMeta(mod.tutorial);
}
